SELECT p.tender_id AS tender_id, (p.seq = t.current_seq) AS cur, p.organization_id AS org, p.role AS role, m.notice_id AS notice_id, m.section_id AS section_id, m.name AS name FROM tender_version_parties p CROSS JOIN tenders t ON t.id = p.tender_id CROSS JOIN organization_mentions m ON m.notice_id = p.mention_notice_id AND m.section_id = p.mention_section_id WHERE p.organization_id = 30953692 AND +m.name NOT LIKE 'Northern Housing%'
UNION ALL
